package com.manishrawat.realestate.servlet;
import com.manishrawat.realestate.dao.MessageDAO; import com.manishrawat.realestate.model.User; import com.manishrawat.realestate.thread.NotificationWorker; import jakarta.servlet.*; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import java.io.*;
@WebServlet("/messages") public class MessageServlet extends HttpServlet{
 protected void doGet(HttpServletRequest q,HttpServletResponse s)throws ServletException,IOException{try{User u=(User)q.getSession(false).getAttribute("user");MessageDAO d=new MessageDAO();q.setAttribute("contacts",d.contacts(u));String other=q.getParameter("with");if(other!=null){int id=Integer.parseInt(other);if(d.canContact(u.getId(),id)){q.setAttribute("conversation",d.conversation(u.getId(),id));q.setAttribute("selectedContact",id);}}q.getRequestDispatcher("/WEB-INF/views/messages.jsp").forward(q,s);}catch(Exception e){throw new ServletException("Unable to load messages.",e);}}
 protected void doPost(HttpServletRequest q,HttpServletResponse s)throws IOException{try{User u=(User)q.getSession(false).getAttribute("user");int to=Integer.parseInt(q.getParameter("receiverId"));String body=q.getParameter("message");MessageDAO d=new MessageDAO();if(body==null||body.isBlank()||body.length()>4000||!d.canContact(u.getId(),to)){s.sendError(400,"Select an eligible contact and enter a message under 4000 characters.");return;}d.send(u.getId(),to,body.trim());NotificationWorker.submit(to,"New message from "+u.getName());s.sendRedirect(q.getContextPath()+"/messages?with="+to);}catch(IllegalArgumentException e){s.sendError(400,"Enter a valid message and eligible contact.");}catch(Exception e){throw new IOException("Unable to send message.",e);}}
}
